// Des: Tests for st-stor-file: roundtrip, dedupe, bomb cap, tamper
// Flo: temp dir > save twice > load > corrupt file > expect errors
// I/O: bytes > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig");
fn rootGet(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); }
test "gzip roundtrip, small and 1 MB" { const allo = std.testing.allocator; const bigz = try allo.alloc(u8, 1 << 20); defer allo.free(bigz); for (bigz, 0..) |*byte, indx| byte.* = @truncate(indx *% 7 / 3); const pack = try file.gzipPack(allo, bigz); defer allo.free(pack); const back = try file.gzipOpen(allo, pack, 2 << 20); defer allo.free(back); try std.testing.expectEqualSlices(u8, bigz, back); const tiny = try file.gzipPack(allo, ""); defer allo.free(tiny); const emty = try file.gzipOpen(allo, tiny, 10); defer allo.free(emty); try std.testing.expectEqual(@as(usize, 0), emty.len); }
test "gzip bomb stops at the cap" { const allo = std.testing.allocator; const zero = try allo.alloc(u8, 4 << 20); defer allo.free(zero); @memset(zero, 0); const pack = try file.gzipPack(allo, zero); defer allo.free(pack); try std.testing.expect(pack.len < 100 * 1024); try std.testing.expectError(error.TooBig, file.gzipOpen(allo, pack, 1 << 20)); }
test "garbage is not gzip" { try std.testing.expectError(error.GzipBad, file.gzipOpen(std.testing.allocator, "not gzip at all, really not", 1000)); }
test "save once, same body again is not fresh, load matches" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const root = try rootGet(&tmpz, &buff); const one = try file.fileSave(allo, std.testing.io, root, "<html>hello</html>"); try std.testing.expect(one.fresh); const two = try file.fileSave(allo, std.testing.io, root, "<html>hello</html>"); try std.testing.expect(!two.fresh); try std.testing.expectEqualSlices(u8, &one.hexz, &two.hexz); const back = try file.fileLoad(allo, std.testing.io, root, one.hexz, 1000); defer allo.free(back); try std.testing.expectEqualStrings("<html>hello</html>", back); const other = try file.fileSave(allo, std.testing.io, root, "<html>bye</html>"); try std.testing.expect(other.fresh); }
test "tampered file is refused" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const root = try rootGet(&tmpz, &buff); const one = try file.fileSave(allo, std.testing.io, root, "original page"); const fake = try file.gzipPack(allo, "evil page"); defer allo.free(fake); var pbuf: [96]u8 = undefined; const rela = try hash.hashPath(&pbuf, one.hexz); const full = try std.fs.path.join(allo, &.{ root, rela }); defer allo.free(full); try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = full, .data = fake }); try std.testing.expectError(error.HashMismatch, file.fileLoad(allo, std.testing.io, root, one.hexz, 1000)); }
test "missing file is an error, no .part left after save" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const root = try rootGet(&tmpz, &buff); try std.testing.expectError(error.FileNotFound, file.fileLoad(allo, std.testing.io, root, hash.hashHex("nothing"), 100)); const one = try file.fileSave(allo, std.testing.io, root, "x"); var pbuf: [96]u8 = undefined; const rela = try hash.hashPath(&pbuf, one.hexz); const part = try std.fmt.allocPrint(allo, "{s}/{s}.part", .{ root, rela }); defer allo.free(part); try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().statFile(std.testing.io, part, .{})); }
